import { JsonValue, Mutation, MutationType } from '@shared/types';

type SchemaRecord = Record<string, unknown>;
function record(value: unknown): SchemaRecord | undefined {
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? value as SchemaRecord : undefined;
}

export class NegativeGeneratorService {
  /**
   * Explores a JSON schema and a valid base payload to generate negative mutations.
   * 
   * @param schema The JSON Schema
   * @param validPayload A valid payload generated by DataGeneratorService
   * @returns A list of potential mutations
   */
  public generateMutations(schema: unknown, validPayload: unknown): Mutation[] {
    const mutations: Mutation[] = [];
    const schemaObject = record(schema);
    const payload = record(validPayload) ?? {};
    const properties = record(schemaObject?.properties);
    if (schemaObject?.type === 'object' && properties) {
      const required = Array.isArray(schemaObject.required) ? schemaObject.required.filter((value): value is string => typeof value === 'string') : [];
      for (const [key, rawPropSchema] of Object.entries(properties)) {
        const propSchema = record(rawPropSchema) ?? {};
        const path = `body.${key}`;
        const originalValue = payload[key];

        // 1. Missing Required
        if (required.includes(key)) {
          const mutatedPayload = { ...payload };
          delete mutatedPayload[key];
          mutations.push({
            type: MutationType.MISSING_REQUIRED,
            targetPath: path,
            originalValue,
            mutatedValue: undefined,
            expectedFailure: '400 Bad Request'
          });
        }

        // 2. Null Violation
        if (propSchema.nullable !== true && propSchema.type !== 'null') {
          mutations.push({
            type: MutationType.NULL_VIOLATION,
            targetPath: path,
            originalValue,
            mutatedValue: null,
            expectedFailure: '400 Bad Request'
          });
        }

        // 3. Type Mismatch
        let badTypeVal: JsonValue | undefined;
        if (propSchema.type === 'string') badTypeVal = 12345;
        else if (propSchema.type === 'integer' || propSchema.type === 'number') badTypeVal = 'not-a-number';
        else if (propSchema.type === 'boolean') badTypeVal = 'true_string';

        if (badTypeVal !== undefined) {
          mutations.push({
            type: MutationType.TYPE_MISMATCH,
            targetPath: path,
            originalValue,
            mutatedValue: badTypeVal,
            expectedFailure: '400 Bad Request'
          });
        }

        // 4. Boundary Violation (e.g. strings that are too long/short, or numbers that are out of bounds)
        if (propSchema.type === 'string' && typeof propSchema.maxLength === 'number' && propSchema.maxLength > 0) {
          mutations.push({
            type: MutationType.BOUNDARY,
            targetPath: path,
            originalValue,
            mutatedValue: 'x'.repeat(Math.min(propSchema.maxLength + 1, 10000)),
            expectedFailure: '400 Bad Request'
          });
        }
        if (propSchema.type === 'string' && typeof propSchema.minLength === 'number' && propSchema.minLength > 0) {
          mutations.push({
            type: MutationType.BOUNDARY,
            targetPath: path,
            originalValue,
            mutatedValue: '',
            expectedFailure: '400 Bad Request'
          });
        }
        if ((propSchema.type === 'integer' || propSchema.type === 'number') && typeof propSchema.minimum === 'number') {
          mutations.push({
            type: MutationType.BOUNDARY,
            targetPath: path,
            originalValue,
            mutatedValue: propSchema.minimum - 1,
            expectedFailure: '400 Bad Request'
          });
        }
        if ((propSchema.type === 'integer' || propSchema.type === 'number') && typeof propSchema.maximum === 'number') {
          mutations.push({
            type: MutationType.BOUNDARY,
            targetPath: path,
            originalValue,
            mutatedValue: propSchema.maximum + 1,
            expectedFailure: '400 Bad Request'
          });
        }

        // 5. Format Violation (e.g. email, uuid, uri)
        if (propSchema.type === 'string' && typeof propSchema.format === 'string') {
          let badFormatVal: string | undefined;
          if (propSchema.format === 'email') badFormatVal = 'invalid-email-address';
          else if (propSchema.format === 'uuid') badFormatVal = 'not-a-valid-uuid-123';
          else if (propSchema.format === 'uri' || propSchema.format === 'url') badFormatVal = 'not-a-valid-url';
          else if (propSchema.format === 'date' || propSchema.format === 'date-time') badFormatVal = 'invalid-date-format';

          if (badFormatVal !== undefined) {
            mutations.push({
              type: MutationType.FORMAT_VIOLATION,
              targetPath: path,
              originalValue,
              mutatedValue: badFormatVal,
              expectedFailure: '400 Bad Request'
            });
          }
        }
      }
    }

    return mutations;
  }
}
